  // ---------- типограф: короткие слова держатся за следующим, тире — за предыдущим ----------
  function nb(t) {
    t = String(t);
    for (var i = 0; i < 2; i++) t = t.replace(/(^|[\s(«>])([А-Яа-яЁёA-Za-z]{1,2})\s/g, '$1$2\u00a0');
    t = t.replace(/(^|[\s(«>])(без|для|про|под|над|при|обо|или|что|как|его|все|еще|уже|это|был|так)\s/gi, '$1$2\u00a0');
    return t.replace(/\s—/g, '\u00a0—').replace(/(\S)-(?=\S)/g, '$1-⁠');
  }
  function nbh(t) {
    t = String(t);
    for (var i = 0; i < 2; i++) t = t.replace(/(^|[\s(«>])([А-Яа-яЁёA-Za-z]{1,2})\s/g, '$1$2\u00a0');
    return t.replace(/\s—/g, '\u00a0—').replace(/\s(\S+)$/, '\u00a0$1');
  }
  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }
  function T(t) { return esc(nb(t)).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>'); }

  // ---------- знак контурами: цветная звезда, черное написание; words — цвета слов; only — только звезда или только слова ----------
  // star: color — цветная, tone — тональный уголок, solid — монолит, cut — с вырубкой; ink — цвет одноцветной версии
  function logo(key, o) {
    o = o || {};
    var g = L.logos[key]; if (!g) return '';
    var s = L.star, st = o.star || 'color', ink = o.ink || '#fff', wc = o.words || (st === 'color' ? [INK, INK] : [ink, ink]);
    var hs = o.free ? '' : ' style="height:calc(var(--u) * ' + (g.h / 100 * (o.k || 1)).toFixed(3) + ')"';
    var star = st === 'color' ? '<path fill="' + BLUE + '" d="' + s.piece + '"/><path fill="' + RED + '" d="' + s.main + '"/>'
      : st === 'tone' ? '<path fill="' + ink + '" fill-opacity=".62" d="' + s.piece + '"/><path fill="' + ink + '" d="' + s.main + '"/>'
      : st === 'cut' ? '<path fill="' + ink + '" fill-rule="evenodd" d="' + s.piece + s.hole + '"/><path fill="' + ink + '" d="' + s.main + '"/>'
      : '<path fill="' + ink + '" d="' + s.solid + '"/>';
    return '<svg xmlns="http://www.w3.org/2000/svg" class="lg' + (o.cls ? ' ' + o.cls : '') + '" viewBox="0 0 ' + g.w + ' ' + g.h + '" width="' + g.w + '" height="' + g.h + '"' + hs + ' role="img" aria-label="армия спорта">' +
      (o.only === 'words' ? '' : '<g transform="translate(' + g.s[0] + ' ' + g.s[1] + ')">' + star + '</g>') +
      (o.only === 'star' ? '' : '<path fill="' + wc[0] + '" d="' + g.d[0] + '"/><path fill="' + wc[1] + '" d="' + g.d[1] + '"/>') + '</svg>';
  }
  // тот же знак картинкой: для блоков, где разметка прошлых этапов ждет img
  function uri(key, o) { o = o || {}; o.free = 1; return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(logo(key, o)); }
  // охранное поле в половину звезды: по бокам — половина ее ширины, сверху и снизу — половина высоты; в поле бледные половинные звезды-мерки
  function guard(key, k) {
    var g = L.logos[key]; if (!g) return '';
    var s = L.star, mx = L.sw / 2, my = 50, W = g.w + 2 * mx, H = g.h + 2 * my;
    function ghost(x, y) { return '<path transform="translate(' + x.toFixed(2) + ' ' + y.toFixed(2) + ') scale(.5)" d="' + s.main + s.piece + '"/>'; }
    var gs = ghost(0, my + g.s[1]) + ghost(mx + g.w, my + g.s[1]) + ghost(mx + g.s[0], 0) + ghost(mx + g.s[0], my + g.h);
    return '<svg class="lg gf" viewBox="-2 -2 ' + (W + 4) + ' ' + (H + 4) + '" width="' + W + '" height="' + H + '" style="height:calc(var(--u) * ' + (H / 100 * (k || 1)).toFixed(3) + ')" role="img" aria-label="армия спорта с охранным полем">' +
      '<rect class="fd" width="' + W + '" height="' + H + '"/><g class="gh">' + gs + '</g><rect class="bx" x="' + mx + '" y="' + my + '" width="' + g.w + '" height="' + g.h + '"/>' +
      '<g transform="translate(' + mx + ' ' + my + ')">' + logo(key, { free: 1 }).replace(/^<svg[^>]*>|<\/svg>$/g, '') + '</g></svg>';
  }
  // имя с s5: — новое фото (s5-wall), по умолчанию s5-tee… для имен ниже; остальные — картинки второго этапа
  var NEW = /^(tee-|fm-)/;
  function ph(name, r) {
    var f = name.indexOf('s5:') === 0 ? 's5-' + name.slice(3) : (NEW.test(name) ? 's5-' : 's2-') + name, big = IMG + f + '.webp', small = IMG + f + '-s.webp';
    return '<div class="as-ph zoom" style="aspect-ratio:' + (r || 1) + '" data-big="' + big + '"><img src="' + small + '" srcset="' + small + ' 820w, ' + big + ' 1400w" sizes="(max-width:640px) 100vw, 50vw" alt="" loading="lazy" decoding="async"></div>';
  }
  function tx(title, ps) {
    return '<div class="as-wrap"><div class="as-tx as-up"><h2 class="as-h2">' + esc(nbh(title)) + '</h2><div>' +
      [].concat(ps || []).map(function (p) { return '<p class="as-p">' + T(p) + '</p>'; }).join('') + '</div></div></div>';
  }
